window.BOOK={"key":"mutanabbihikam","app":"mutoon-mutanabbihikam","lsk":"mutoon_mutanabbihikam_v1","prefix":"mu_","title":"على قدر أهل العزم","sub":"الشعر العربي · المتنبي (ت ٣٥٤هـ) · ٤٦ بيتًا","poems":[{"id":"mutanabbihikam","title":"على قدر أهل العزم","nazim":"أبو الطيب أحمد بن الحسين المتنبي","death":"ت ٣٥٤هـ","meter":"الطويل","source":"موقع الديوان (نص الموسوعة الشعرية المشكول): «على قدر أهل العزم تأتي العزائم»","srcUrl":"https://www.aldiwan.net/poem10524.html","note":"ميمية المتنبي في سيف الدولة وبناء الحدث (٤٦ بيتًا)، قوبلت كلمةً كلمةً بسكربت بطبعة عبد الوهاب عزام المحققة (لجنة التأليف والترجمة والنشر) وبنص ويكي مصدر المشكول، واعتُمدت قراءة الأغلبية حيث اختلفت. أُكمل من الشكل ما يقتضيه اصطلاح المصدر، وصُحّحت أخطاء ظاهرة، والتفصيل في تقرير المصادر.","verses":[["عَلَى قَدْرِ أَهْلِ الْعَزْمِ تَأْتِي الْعَزَائِمُ","وَتَأْتِي عَلَى قَدْرِ الْكِرَامِ الْمَكَارِمُ"],["وَتَعْظُمُ فِي عَيْنِ الصَّغِيرِ صِغَارُهَا","وَتَصْغُرُ فِي عَيْنِ الْعَظِيمِ الْعَظَائِمُ"],["يُكَلِّفُ سَيْفُ الدَّوْلَةِ الْجَيْشَ هَمَّهُ","وَقَدْ عَجَزَتْ عَنْهُ الْجُيُوشُ الْخَضَارِمُ"],["وَيَطْلُبُ عِنْدَ النَّاسِ مَا عِنْدَ نَفْسِهِ","وَذَلِكَ مَا لَا تَدَّعِيهِ الضَّرَاغِمُ"],["يُفَدِّي أَتَمُّ الطَّيْرِ عُمْرًا سِلَاحَهُ","نُسُورُ الْمَلَا أَحْدَاثُهَا وَالْقَشَاعِمُ"],["وَمَا ضَرَّهَا خَلْقٌ بِغَيْرِ مَخَالِبٍ","وَقَدْ خُلِقَتْ أَسْيَافُهُ وَالْقَوَائِمُ"],["هَلِ الْحَدَثُ الْحَمْرَاءُ تَعْرِفُ لَوْنَهَا","وَتَعْلَمُ أَيُّ السَّاقِيَيْنِ الْغَمَائِمُ"],["سَقَتْهَا الْغَمَامُ الْغُرُّ قَبْلَ نُزُولِهِ","فَلَمَّا دَنَا مِنْهَا سَقَتْهَا الْجَمَاجِمُ"],["بَنَاهَا فَأَعْلَى وَالْقَنَا يَقْرَعُ الْقَنَا","وَمَوْجُ الْمَنَايَا حَوْلَهَا مُتَلَاطِمُ"],["وَكَانَ بِهَا مِثْلُ الْجُنُونِ فَأَصْبَحَتْ","وَمِنْ جُثَثِ الْقَتْلَى عَلَيْهَا تَمَائِمُ"],["طَرِيدَةُ دَهْرٍ سَاقَهَا فَرَدَدْتَهَا","عَلَى الدِّينِ بِالْخَطِّيِّ وَالدَّهْرُ رَاغِمُ"],["تُفِيتُ اللَّيَالِي كُلَّ شَيْءٍ أَخَذْتَهُ","وَهُنَّ لِمَا يَأْخُذْنَ مِنْكَ غَوَارِمُ"],["إِذَا كَانَ مَا تَنْوِيهِ فِعْلًا مُضَارِعًا","مَضَى قَبْلَ أَنْ تُلْقَى عَلَيْهِ الْجَوَازِمُ"],["وَكَيْفَ تُرَجِّي الرُّومُ وَالرُّوسُ هَدْمَهَا","وَذَا الطَّعْنُ آسَاسٌ لَهَا وَدَعَائِمُ"],["وَقَدْ حَاكَمُوهَا وَالْمَنَايَا حَوَاكِمٌ","فَمَا مَاتَ مَظْلُومٌ وَلَا عَاشَ ظَالِمُ"],["أَتَوْكَ يَجُرُّونَ الْحَدِيدَ كَأَنَّهُمْ","سَرَوْا بِجِيَادٍ مَا لَهُنَّ قَوَائِمُ"],["إِذَا بَرَقُوا لَمْ تُعْرَفِ الْبِيضُ مِنْهُمُ","ثِيَابُهُمُ مِنْ مِثْلِهَا وَالْعَمَائِمُ"],["خَمِيسٌ بِشَرْقِ الْأَرْضِ وَالْغَرْبِ زَحْفُهُ","وَفِي أُذُنِ الْجَوْزَاءِ مِنْهُ زَمَازِمُ"],["تَجَمَّعَ فِيهِ كُلُّ لِسْنٍ وَأُمَّةٍ","فَمَا تُفْهِمُ الْحُدَّاثَ إِلَّا التَّرَاجِمُ"],["فَلِلَّهِ وَقْتٌ ذَوَّبَ الْغِشَّ نَارُهُ","فَلَمْ يَبْقَ إِلَّا صَارِمٌ أَوْ ضُبَارِمُ"],["تَقَطَّعَ مَا لَا يَقْطَعُ الدِّرْعَ وَالْقَنَا","وَفَرَّ مِنَ الْفُرْسَانِ مَنْ لَا يُصَادِمُ"],["وَقَفْتَ وَمَا فِي الْمَوْتِ شَكٌّ لِوَاقِفٍ","كَأَنَّكَ فِي جَفْنِ الرَّدَى وَهْوَ نَائِمُ"],["تَمُرُّ بِكَ الْأَبْطَالُ كَلْمَى هَزِيمَةً","وَوَجْهُكَ وَضَّاحٌ وَثَغْرُكَ بَاسِمُ"],["تَجَاوَزْتَ مِقْدَارَ الشَّجَاعَةِ وَالنُّهَى","إِلَى قَوْلِ قَوْمٍ أَنْتَ بِالْغَيْبِ عَالِمُ"],["ضَمَمْتَ جَنَاحَيْهِمْ عَلَى الْقَلْبِ ضَمَّةً","تَمُوتُ الْخَوَافِي تَحْتَهَا وَالْقَوَادِمُ"],["بِضَرْبٍ أَتَى الْهَامَاتِ وَالنَّصْرُ غَائِبٌ","وَصَارَ إِلَى اللَّبَّاتِ وَالنَّصْرُ قَادِمُ"],["حَقَرْتَ الرُّدَيْنِيَّاتِ حَتَّى طَرَحْتَهَا","وَحَتَّى كَأَنَّ السَّيْفَ لِلرُّمْحِ شَاتِمُ"],["وَمَنْ طَلَبَ الْفَتْحَ الْجَلِيلَ فَإِنَّمَا","مَفَاتِيحُهُ الْبِيضُ الْخِفَافُ الصَّوَارِمُ"],["نَثَرْتَهُمُ فَوْقَ الْأُحَيْدِبِ كُلِّهِ","كَمَا نُثِرَتْ فَوْقَ الْعَرُوسِ الدَّرَاهِمُ"],["تَدُوسُ بِكَ الْخَيْلُ الْوُكُورَ عَلَى الذُّرَى","وَقَدْ كَثُرَتْ حَوْلَ الْوُكُورِ الْمَطَاعِمُ"],["تَظُنُّ فِرَاخُ الْفُتْخِ أَنَّكَ زُرْتَهَا","بِأُمَّاتِهَا وَهْيَ الْعِتَاقُ الصَّلَادِمُ"],["إِذَا زَلِقَتْ مَشَّيْتَهَا بِبُطُونِهَا","كَمَا تَتَمَشَّى فِي الصَّعِيدِ الْأَرَاقِمُ"],["أَفِي كُلِّ يَوْمٍ ذَا الدُّمُسْتُقُ مُقْدِمٌ","قَفَاهُ عَلَى الْإِقْدَامِ لِلْوَجْهِ لَائِمُ"],["أَيُنْكِرُ رِيحَ اللَّيْثِ حَتَّى يَذُوقَهُ","وَقَدْ عَرَفَتْ رِيحَ اللُّيُوثِ الْبَهَائِمُ"],["وَقَدْ فَجَعَتْهُ بِابْنِهِ وَابْنِ صِهْرِهِ","وَبِالصِّهْرِ حَمْلَاتُ الْأَمِيرِ الْغَوَاشِمُ"],["مَضَى يَشْكُرُ الْأَصْحَابَ فِي فَوْتِهِ الظُّبَى","لِمَا شَغَلَتْهَا هَامُهُمْ وَالْمَعَاصِمُ"],["وَيَفْهَمُ صَوْتَ الْمَشْرَفِيَّةِ فِيهِمِ","عَلَى أَنَّ أَصْوَاتَ السُّيُوفِ أَعَاجِمُ"],["يُسَرُّ بِمَا أَعْطَاكَ لَا عَنْ جَهَالَةٍ","وَلَكِنَّ مَغْنُومًا نَجَا مِنْكَ غَانِمُ"],["وَلَسْتَ مَلِيكًا هَازِمًا لِنَظِيرِهِ","وَلَكِنَّكَ التَّوْحِيدُ لِلشِّرْكِ هَازِمُ"],["تَشَرَّفُ عَدْنَانٌ بِهِ لَا رَبِيعَةٌ","وَتَفْتَخِرُ الدُّنْيَا بِهِ لَا الْعَوَاصِمُ"],["لَكَ الْحَمْدُ فِي الدُّرِّ الَّذِي لِيَ لَفْظُهُ","فَإِنَّكَ مُعْطِيهِ وَإِنِّيَ نَاظِمُ"],["وَإِنِّي لَتَعْدُو بِي عَطَايَاكَ فِي الْوَغَى","فَلَا أَنَا مَذْمُومٌ وَلَا أَنْتَ نَادِمُ"],["عَلَى كُلِّ طَيَّارٍ إِلَيْهَا بِرِجْلِهِ","إِذَا وَقَعَتْ فِي مِسْمَعَيْهِ الْغَمَاغِمُ"],["أَلَا أَيُّهَا السَّيْفُ الَّذِي لَيْسَ مُغْمَدًا","وَلَا فِيهِ مُرْتَابٌ وَلَا مِنْهُ عَاصِمُ"],["هَنِيئًا لِضَرْبِ الْهَامِ وَالْمَجْدِ وَالْعُلَى","وَرَاجِيكَ وَالْإِسْلَامِ أَنَّكَ سَالِمُ"],["وَلِمْ لَا يَقِي الرَّحْمَنُ حَدَّيْكَ مَا وَقَى","وَتَفْلِيقُهُ هَامَ الْعِدَى بِكَ دَائِمُ"]],"secs":{"1":"على قدر أهل العزم تأتي العزائم"}}],"sharh":false};
